6	namespace llm_npc {
7	
8	// Minimal 3D vector used for world positions, movement, and the camera.
9	// Kept SFML-free so core logic and unit tests build without graphics libs.
10	struct Vec3 {
11	    float x = 0.f;
12	    float y = 0.f;
13	    float z = 0.f;
14	};
15	
16	// Component-wise vector sum.
17	inline Vec3 operator+(const Vec3& a, const Vec3& b) { return {a.x + b.x, a.y + b.y, a.z + b.z}; }
18	
19	// Component-wise vector difference.
20	inline Vec3 operator-(const Vec3& a, const Vec3& b) { return {a.x - b.x, a.y - b.y, a.z - b.z}; }
21	
22	// Scale a vector by a scalar.
23	inline Vec3 operator*(const Vec3& v, float s) { return {v.x * s, v.y * s, v.z * s}; }
24	
25	// In-place component-wise sum.
26	inline Vec3& operator+=(Vec3& a, const Vec3& b) {
27	    a.x += b.x;
28	    a.y += b.y;
29	    a.z += b.z;
30	    return a;
31	}
32	
33	// Dot product.
34	inline float dot(const Vec3& a, const Vec3& b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
35	
36	// Cross product (right-handed).
37	inline Vec3 cross(const Vec3& a, const Vec3& b) {
38	    return {a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x};
39	}
40	
41	// Euclidean length.
42	inline float length(const Vec3& v) { return std::sqrt(dot(v, v)); }
43	
44	// Unit-length copy of v; returns v unchanged when its length is ~zero.
45	inline Vec3 normalize(const Vec3& v) {
46	    const float len = length(v);
47	    if (len < 1e-6f) return v;
48	    return v * (1.f / len);
49	}
50	
51	// Distance between two points, ignoring the vertical (y) axis. Used for
52	// ground-plane queries like "is the player near this NPC".
53	inline float distanceXZ(const Vec3& a, const Vec3& b) {
54	    const float dx = a.x - b.x;
55	    const float dz = a.z - b.z;
56	    return std::sqrt(dx * dx + dz * dz);
57	}
58	
59	// Clamp v into [lo, hi].
60	inline float clampf(float v, float lo, float hi) { return std::max(lo, std::min(hi, v)); }
61	
62	// Degrees -> radians.
63	inline float degToRad(float deg) { return deg * 3.14159265358979323846f / 180.f; }
64	
65	}  // namespace llm_npc
