9	namespace llm_npc {
10	
11	// One parsed line of Ollama's streaming /api/chat response (NDJSON).
12	// Exactly one of these situations holds per line:
13	//   - delta carries a fragment of assistant text (possibly empty on the
14	//     final line), done tells us whether the stream is complete;
15	//   - error is non-empty when the line was an {"error": ...} payload or
16	//     could not be parsed at all.
17	struct OllamaChunk {
18	    std::string delta;
19	    bool done = false;
20	    std::string error;
21	};
22	
23	// Parses a single newline-delimited JSON line from Ollama's streaming chat
24	// endpoint. Blank lines yield an empty chunk (no delta, not done, no error)
25	// so callers can simply ignore them.
26	inline OllamaChunk parseOllamaChunk(const std::string& line) {
27	    OllamaChunk chunk;
28	
29	    // Tolerate \r\n framing and skip keep-alive blank lines.
30	    std::string trimmed = line;
31	    while (!trimmed.empty() && (trimmed.back() == '\r' || trimmed.back() == ' ')) {
32	        trimmed.pop_back();
33	    }
34	    if (trimmed.empty()) return chunk;
35	
36	    nlohmann::json parsed = nlohmann::json::parse(trimmed, nullptr, /*allow_exceptions=*/false);
37	    if (parsed.is_discarded()) {
38	        chunk.error = "unparseable stream line from Ollama";
39	        return chunk;
40	    }
41	    if (parsed.contains("error")) {
42	        chunk.error = parsed["error"].is_string() ? parsed["error"].get<std::string>()
43	                                                  : parsed["error"].dump();
44	        if (chunk.error.empty()) chunk.error = "unknown Ollama error";
45	        return chunk;
46	    }
47	    if (parsed.contains("message") && parsed["message"].contains("content") &&
48	        parsed["message"]["content"].is_string()) {
49	        chunk.delta = parsed["message"]["content"].get<std::string>();
50	    }
51	    chunk.done = parsed.value("done", false);
52	    return chunk;
53	}
54	
55	// Reassembles newline-delimited lines from arbitrary byte slices, as
56	// delivered by an HTTP content receiver. Bytes for a line may arrive split
57	// across any number of feed() calls; onLine fires once per complete line
58	// (without the trailing '\n').
59	class StreamAssembler {
60	   public:
61	    // Append bytes; invokes onLine for every completed line found.
62	    void feed(std::string_view bytes, const std::function<void(const std::string&)>& onLine) {
63	        std::size_t start = 0;
64	        while (start < bytes.size()) {
65	            const std::size_t nl = bytes.find('\n', start);
66	            if (nl == std::string_view::npos) {
67	                buffer_.append(bytes.substr(start));
68	                return;
69	            }
70	            buffer_.append(bytes.substr(start, nl - start));
71	            onLine(buffer_);
72	            buffer_.clear();
73	            start = nl + 1;
74	        }
75	    }
76	
77	    // Returns and clears any trailing bytes that never saw a '\n'
78	    // (end-of-stream flush).
79	    std::string takeRemainder() {
80	        std::string out;
81	        out.swap(buffer_);
82	        return out;
83	    }
84	
85	   private:
86	    std::string buffer_;
87	};
88	
89	}  // namespace llm_npc
