8	std::string trim(const std::string& s) {
9	    auto b = s.find_first_not_of(" \t\r\n");
10	    if (b == std::string::npos) return {};
11	    auto e = s.find_last_not_of(" \t\r\n");
12	    return s.substr(b, e - b + 1);
13	}
14	
15	std::unordered_map<std::string, std::string> readKv(const std::filesystem::path& path) {
16	    std::unordered_map<std::string, std::string> out;
17	    std::ifstream in(path);
18	    if (!in) return out;
19	    std::string line;
20	    while (std::getline(in, line)) {
21	        auto hash = line.find('#');
22	        if (hash != std::string::npos) line = line.substr(0, hash);
23	        line = trim(line);
24	        if (line.empty()) continue;
25	        auto eq = line.find('=');
26	        if (eq == std::string::npos) continue;
27	        out[trim(line.substr(0, eq))] = trim(line.substr(eq + 1));
28	    }
29	    return out;
30	}
31	
32	std::string slurp(const std::filesystem::path& path) {
33	    std::ifstream in(path);
34	    if (!in) return {};
35	    std::ostringstream o;
36	    o << in.rdbuf();
37	    return o.str();
38	}
39	
40	LlmConfig loadLlmConfig(const std::filesystem::path& configDir) {
41	    LlmConfig cfg;
42	    auto kv = readKv(configDir / "llm.cfg");
43	    if (auto it = kv.find("host"); it != kv.end()) cfg.host = it->second;
44	    if (auto it = kv.find("port"); it != kv.end()) cfg.port = std::stoi(it->second);
45	    if (auto it = kv.find("model"); it != kv.end()) cfg.model = it->second;
46	    if (auto it = kv.find("temperature"); it != kv.end()) cfg.temperature = std::stod(it->second);
47	    if (auto it = kv.find("request_timeout_s"); it != kv.end()) {
48	        cfg.requestTimeoutSeconds = std::stoi(it->second);
49	    }
50	    return cfg;
51	}
52	
53	}  // namespace llm_npc
