41	PersonaParseResult parsePersonaText(const std::string& text, const std::string& id) {
42	    PersonaParseResult result;
43	    result.value.id = id;
44	
45	    std::istringstream in(text);
46	    std::string line;
47	    std::ostringstream extra;
48	    bool inExtra = false;
49	
50	    while (std::getline(in, line)) {
51	        if (!inExtra) {
52	            const std::string t = trim(line);
53	            if (t == "---") {
54	                inExtra = true;
55	                continue;
56	            }
57	            if (t.empty()) continue;
58	            const auto eq = t.find('=');
59	            if (eq == std::string::npos) {
60	                result.error = id + ": header line without '=': " + t;
61	                return result;
62	            }
63	            const std::string key = trim(t.substr(0, eq));
64	            const std::string val = trim(t.substr(eq + 1));
65	            if (key == "name") {
66	                result.value.persona.name = val;
67	            } else if (key == "role") {
68	                result.value.persona.role = val;
69	            } else if (key == "traits") {
70	                result.value.persona.traits = splitCsv(val);
71	            } else if (key == "style") {
72	                result.value.persona.speakingStyle = val;
73	            } else if (key == "knowledge") {
74	                result.value.persona.knowledgeBoundary = val;
75	            } else if (key == "spot") {
76	                result.value.spotId = val;
77	            } else if (key == "position") {
78	                if (!parsePosition(val, result.value.position)) {
79	                    result.error = id + ": bad position '" + val + "' (want: x, z)";
80	                    return result;
81	                }
82	            } else if (key == "facing") {
83	                try {
84	                    result.value.facingDeg = std::stof(val);
85	                } catch (const std::exception&) {
86	                    result.error = id + ": bad facing '" + val + "'";
87	                    return result;
88	                }
89	            } else {
90	                result.error = id + ": unknown header key '" + key + "'";
91	                return result;
92	            }
93	        } else {
94	            extra << line << '\n';
95	        }
96	    }
97	
98	    if (result.value.persona.name.empty()) {
99	        result.error = id + ": missing required 'name'";
100	        return result;
101	    }
102	    result.value.persona.extraDirectives = trim(extra.str());
103	    result.ok = true;
104	    return result;
105	}
106	
107	PersonaParseResult parsePersonaFile(const std::filesystem::path& path) {
108	    const std::string id = path.stem().string();
109	    std::ifstream in(path);
110	    if (!in) {
111	        PersonaParseResult result;
112	        result.error = id + ": cannot open " + path.string();
113	        return result;
114	    }
115	    std::ostringstream buf;
116	    buf << in.rdbuf();
117	    return parsePersonaText(buf.str(), id);
118	}
119	
120	std::vector<LoadedPersona> loadAllPersonas(const std::filesystem::path& dir,
121	                                           std::vector<std::string>* errors) {
122	    std::vector<std::filesystem::path> files;
123	    std::error_code ec;
124	    for (const auto& entry : std::filesystem::directory_iterator(dir, ec)) {
125	        if (entry.is_regular_file() && entry.path().extension() == ".persona") {
126	            files.push_back(entry.path());
127	        }
128	    }
129	    std::sort(files.begin(), files.end());
130	
131	    std::vector<LoadedPersona> out;
132	    for (const auto& f : files) {
133	        PersonaParseResult r = parsePersonaFile(f);
134	        if (r.ok) {
135	            out.push_back(std::move(r.value));
136	        } else if (errors) {
137	            errors->push_back(r.error);
138	        }
139	    }
140	    return out;
141	}
142	
143	}  // namespace llm_npc
