10	// An axis-aligned solid block of the city: a building, kiosk, fountain,
11	// parked car — anything the player cannot walk through.
12	struct Building {
13	    std::string id;    // stable identifier, e.g. "bakery"
14	    std::string name;  // sign / label text; empty for filler and obstacles
15	    float minX = 0.f;
16	    float minZ = 0.f;
17	    float maxX = 0.f;
18	    float maxZ = 0.f;
19	    float height = 0.f;
20	    int facadeKind = 0;  // texture/tint selector for the renderer
21	};
22	
23	// The walkable city: a square ground plane bounded at +-halfSize() with
24	// solid axis-aligned buildings. Collision treats the player as a circle on
25	// the ground (XZ) plane.
26	class City {
27	   public:
28	    // The hand-laid downtown map: 3x3 blocks, named shops on street fronts,
29	    // an open plaza in the middle, and a park in the north-east corner.
30	    static City makeDowntown();
31	
32	    // Half the side length of the square world; walkable X/Z are within
33	    // [-halfSize, halfSize].
34	    float halfSize() const { return halfSize_; }
35	
36	    const std::vector<Building>& buildings() const { return buildings_; }
37	
38	    // Find a building by id; nullptr when absent.
39	    const Building* findBuilding(const std::string& id) const;
40	
41	    // True when a circle at (x, z) with `radius` overlaps any building.
42	    bool circleIntersectsAny(float x, float z, float radius) const;
43	
44	    // Move a circle of `radius` from `from` toward `to`, sliding along
45	    // obstacles: each axis is applied independently and dropped if it would
46	    // collide, so walking diagonally into a wall glides along it.
47	    // The result is also clamped to the world bounds. y passes through.
48	    Vec3 resolveMovement(const Vec3& from, const Vec3& to, float radius) const;
49	
50	   private:
51	    float halfSize_ = 110.f;
52	    std::vector<Building> buildings_;
53	};
54	
55	}  // namespace llm_npc
