7	// Squared distance from point (x, z) to the nearest point of building b.
8	float distSqToBuilding(const Building& b, float x, float z) {
9	    const float cx = clampf(x, b.minX, b.maxX);
10	    const float cz = clampf(z, b.minZ, b.maxZ);
11	    const float dx = x - cx;
12	    const float dz = z - cz;
13	    return dx * dx + dz * dz;
14	}
15	
16	}  // namespace
17	
18	City City::makeDowntown() {
19	    // Layout reference: 3x3 city blocks on a 64-unit pitch. Block centers sit
20	    // at -64/0/64 on each axis and each block spans +-24 around its center,
21	    // leaving 16-unit streets between blocks. The center block is an open
22	    // plaza; the north-east block is a park.
23	    City city;
24	    city.halfSize_ = 110.f;
25	    city.buildings_ = {
26	        // Named shops, fronts flush with their street edge.
27	        {"bakery", "Marge's Bakery", -84.f, -64.f, -56.f, -40.f, 12.f, 0},
28	        {"police", "City Police Station", -20.f, -80.f, 20.f, -40.f, 16.f, 1},
29	        {"coffee", "Bean There Coffee", 44.f, -62.f, 72.f, -40.f, 10.f, 2},
30	        {"library", "City Library", -80.f, -16.f, -40.f, 16.f, 15.f, 3},
31	        {"hardware", "Jensen Hardware", 40.f, -14.f, 72.f, 14.f, 11.f, 4},
32	
33	        // Plaza furniture and street props (low obstacles).
34	        {"cart", "Gus's Hot Dogs", -3.f, -2.f, 3.f, 2.f, 3.f, 5},
35	        {"taxi_cab", "", 26.f, -6.f, 34.f, -1.f, 1.6f, 6},
36	        {"fountain", "", 60.f, 56.f, 68.f, 64.f, 1.5f, 7},
37	        {"bench", "", 66.f, 70.f, 70.f, 71.f, 0.6f, 8},
38	
39	        // Unnamed filler so every block reads as a dense city.
40	        {"apt_a", "", -88.f, -88.f, -68.f, -70.f, 22.f, 9},
41	        {"apt_b", "", -60.f, -88.f, -40.f, -72.f, 18.f, 9},
42	        {"office_a", "", 44.f, -88.f, 88.f, -66.f, 26.f, 10},
43	        {"apts_c", "", -88.f, 44.f, -44.f, 84.f, 24.f, 9},
44	        {"tower", "", -24.f, 48.f, 24.f, 88.f, 30.f, 10},
45	    };
46	    return city;
47	}
48	
49	const Building* City::findBuilding(const std::string& id) const {
50	    for (const auto& b : buildings_) {
51	        if (b.id == id) return &b;
52	    }
53	    return nullptr;
54	}
55	
56	bool City::circleIntersectsAny(float x, float z, float radius) const {
57	    const float r2 = radius * radius;
58	    for (const auto& b : buildings_) {
59	        if (distSqToBuilding(b, x, z) < r2) return true;
60	    }
61	    return false;
62	}
63	
64	Vec3 City::resolveMovement(const Vec3& from, const Vec3& to, float radius) const {
65	    const float lo = -halfSize_ + radius;
66	    const float hi = halfSize_ - radius;
67	
68	    Vec3 pos = from;
69	    const float nx = clampf(to.x, lo, hi);
70	    if (!circleIntersectsAny(nx, pos.z, radius)) pos.x = nx;
71	    const float nz = clampf(to.z, lo, hi);
72	    if (!circleIntersectsAny(pos.x, nz, radius)) pos.z = nz;
73	    pos.y = to.y;
74	    return pos;
75	}
76	
77	}  // namespace llm_npc
