12	// Canonicalize a key name: single letters become uppercase so "w" and "W"
13	// refer to the same key; multi-character names ("Escape") pass through.
14	std::string canonical(std::string name) {
15	    if (name.size() == 1) name[0] = static_cast<char>(std::toupper(name[0]));
16	    return name;
17	}
18	
19	constexpr std::array<const char*, kActionCount> kActionNames = {
20	    "move_forward", "move_backward", "strafe_left", "strafe_right", "talk", "menu",
21	};
22	
23	constexpr std::array<const char*, kActionCount> kActionLabels = {
24	    "Move forward", "Move backward", "Strafe left", "Strafe right", "Talk to NPC", "Open menu",
25	};
26	
27	}  // namespace
28	
29	KeyBindings KeyBindings::defaults() {
30	    KeyBindings kb;
31	    kb.keys_ = {"W", "S", "A", "D", "T", "Escape"};
32	    return kb;
33	}
34	
35	const char* KeyBindings::actionName(Action a) {
36	    return kActionNames[static_cast<std::size_t>(a)];
37	}
38	
39	const char* KeyBindings::actionLabel(Action a) {
40	    return kActionLabels[static_cast<std::size_t>(a)];
41	}
42	
43	const std::string& KeyBindings::key(Action a) const {
44	    return keys_[static_cast<std::size_t>(a)];
45	}
46	
47	std::optional<Action> KeyBindings::actionForKey(const std::string& keyName) const {
48	    const std::string canon = canonical(keyName);
49	    if (canon.empty()) return std::nullopt;
50	    for (std::size_t i = 0; i < kActionCount; ++i) {
51	        if (keys_[i] == canon) return static_cast<Action>(i);
52	    }
53	    return std::nullopt;
54	}
55	
56	std::optional<Action> KeyBindings::rebind(Action a, const std::string& keyName) {
57	    const std::string canon = canonical(keyName);
58	    const std::size_t idx = static_cast<std::size_t>(a);
59	    if (canon.empty() || keys_[idx] == canon) return std::nullopt;
60	
61	    std::optional<Action> displaced = actionForKey(canon);
62	    if (displaced) {
63	        // Swap: the displaced action inherits this action's old key.
64	        keys_[static_cast<std::size_t>(*displaced)] = keys_[idx];
65	    }
66	    keys_[idx] = canon;
67	    return displaced;
68	}
69	
70	bool KeyBindings::load(const std::filesystem::path& path) {
71	    *this = defaults();
72	    auto kv = readKv(path);
73	    if (kv.empty()) return false;
74	
75	    const KeyBindings def = defaults();
76	    for (std::size_t i = 0; i < kActionCount; ++i) {
77	        if (auto it = kv.find(kActionNames[i]); it != kv.end()) {
78	            keys_[i] = canonical(it->second);
79	        }
80	    }
81	
82	    // Deduplicate: earliest action in enum order keeps a contested key.
83	    for (std::size_t i = 0; i < kActionCount; ++i) {
84	        bool taken = false;
85	        for (std::size_t j = 0; j < i; ++j) {
86	            if (!keys_[i].empty() && keys_[j] == keys_[i]) taken = true;
87	        }
88	        if (!taken) continue;
89	        // Fall back to this action's default unless that is taken too.
90	        std::string fallback = def.keys_[i];
91	        for (std::size_t j = 0; j < kActionCount; ++j) {
92	            if (j != i && keys_[j] == fallback) fallback.clear();
93	        }
94	        keys_[i] = fallback;
95	    }
96	    return true;
97	}
98	
99	bool KeyBindings::save(const std::filesystem::path& path) const {
100	    std::ofstream out(path);
101	    if (!out) return false;
102	    out << "# Key bindings. Edit in-game via the menu, or by hand here.\n";
103	    for (std::size_t i = 0; i < kActionCount; ++i) {
104	        out << kActionNames[i] << " = " << keys_[i] << '\n';
105	    }
106	    return static_cast<bool>(out);
