1	#include "DialogueSession.hpp"
2	
3	namespace llm_npc {
4	
5	void DialogueSession::open(int npcIndex) {
6	    state_ = State::Talking;
7	    npcIndex_ = npcIndex;
8	    pendingId_ = 0;
9	    streamingText_.clear();
10	}
11	
12	void DialogueSession::close() {
13	    state_ = State::Roaming;
14	    npcIndex_ = -1;
15	    pendingId_ = 0;
16	    streamingText_.clear();
17	}
18	
19	void DialogueSession::submitted(std::uint64_t requestId) {
20	    if (state_ != State::Talking) return;
21	    pendingId_ = requestId;
22	    streamingText_.clear();
23	    state_ = State::WaitingReply;
24	}
25	
26	bool DialogueSession::deltaArrived(std::uint64_t id, const std::string& text) {
27	    if (state_ != State::WaitingReply && state_ != State::Streaming) return false;
28	    if (id == 0 || id != pendingId_) return false;
29	    streamingText_ += text;
30	    state_ = State::Streaming;
31	    return true;
32	}
33	
34	bool DialogueSession::replyArrived(std::uint64_t id, bool /*ok*/) {
35	    if (state_ != State::WaitingReply && state_ != State::Streaming) return false;
36	    if (id == 0 || id != pendingId_) return false;
37	    pendingId_ = 0;
38	    streamingText_.clear();
39	    state_ = State::Talking;
40	    return true;
41	}
42	
43	}  // namespace llm_npc
