48	    // Just outside the cart: x = 3 (cart edge) + 0.7 clearance, radius 0.6.
49	    CHECK_FALSE(city.circleIntersectsAny(3.7f, 0.f, 0.6f));
50	    // Touching via the radius: x = 3.4 means the 0.6 circle reaches 2.8 < 3.0.
51	    CHECK(city.circleIntersectsAny(3.5f, 0.f, 0.6f));
