22	    int port = 11434;
23	    std::string model = "qwen2.5:3b-instruct";
24	    double temperature = 0.8;
25	    int requestTimeoutSeconds = 60;
26	    // Passed to Ollama as keep_alive so the model stays loaded between
27	    // conversations instead of paying the cold-start cost every time.
28	    std::string keepAlive = "10m";
29	};
