31	// One request submitted to the LLM.
32	struct ChatRequest {
33	    std::uint64_t id = 0;
34	    std::string systemPrompt;
35	    std::vector<ChatTurn> history;
36	    std::string userMessage;
37	    // Internal requests (model warm-up) never produce a ChatReply or deltas.
38	    bool internal = false;
39	};
