41	// One incremental fragment of an in-flight streamed reply, surfaced to the
42	// main thread via drainDeltas() so the UI can show words as they arrive.
43	struct ChatDelta {
44	    std::uint64_t id = 0;
45	    std::string text;
46	};
47	
48	// One reply pulled off the queue on the main thread.
49	struct ChatReply {
50	    std::uint64_t id = 0;
51	    bool ok = false;
52	    std::string content;       // model's reply when ok
53	    std::string errorMessage;  // human-readable error when !ok
54	};
55	
56	// Centralized LLM access point. One worker thread serves all NPCs.
57	// Callers submit() requests from the main thread, drainDeltas() each frame to
58	// stream partial text, and drainReplies() to receive completed replies. The
59	// id returned from submit() lets callers match deltas and replies back to the
60	// request they sent.
61	class LlmClient {
62	   public:
63	    explicit LlmClient(LlmConfig config);
64	    ~LlmClient();
65	
66	    LlmClient(const LlmClient&) = delete;
67	    LlmClient& operator=(const LlmClient&) = delete;
68	
69	    // Enqueue a chat request. Returns a unique id used to correlate replies.
70	    std::uint64_t submit(std::string systemPrompt,
71	                         std::vector<ChatTurn> history,
72	                         std::string userMessage);
73	
74	    // Enqueue an internal request that makes Ollama load the model into
75	    // memory (empty messages + keep_alive). Produces no deltas and no reply;
76	    // call once at startup so the first real conversation answers fast.
77	    void warmUp();
78	
79	    // Pop all streamed text fragments that arrived since the last call.
80	    // Non-blocking; fragments are in arrival order.
81	    std::vector<ChatDelta> drainDeltas();
82	
83	    // Pop all replies that have arrived since the last call. Non-blocking.
84	    std::vector<ChatReply> drainReplies();
85	
86	    // True while at least one request is in flight or queued. Useful for UI.
87	    bool busy() const { return inFlight_.load(); }
88	
89	    const LlmConfig& config() const { return config_; }
90	
91	   private:
92	    void workerLoop();
93	    ChatReply processOne(const ChatRequest& req);
94	    void enqueue(ChatRequest req);
95	
96	    LlmConfig config_;
97	
98	    std::thread worker_;
99	    std::atomic<bool> stop_{false};
100	    std::atomic<bool> inFlight_{false};
101	
102	    std::mutex requestMutex_;
103	    std::condition_variable requestCv_;
104	    std::queue<ChatRequest> requests_;
105	
106	    std::mutex replyMutex_;
107	    std::vector<ChatReply> replies_;
108	    std::vector<ChatDelta> deltas_;
109	
110	    std::atomic<std::uint64_t> nextId_{1};
111	};
