67	void LlmClient::workerLoop() {
68	    while (true) {
69	        ChatRequest req;
70	        {
71	            std::unique_lock<std::mutex> lock(requestMutex_);
72	            requestCv_.wait(lock, [this] { return stop_.load() || !requests_.empty(); });
73	            if (stop_.load() && requests_.empty()) return;
74	            req = std::move(requests_.front());
75	            requests_.pop();
76	        }
77	
78	        inFlight_.store(true);
79	        ChatReply reply = processOne(req);
80	        if (!req.internal) {
81	            std::lock_guard<std::mutex> lock(replyMutex_);
82	            replies_.push_back(std::move(reply));
83	        }
84	        // Drop the flag only after the reply is queued so UI can poll busy()
85	        // without seeing a brief idle window before the reply lands.
86	        inFlight_.store(false);
87	    }
88	}
