90	ChatReply LlmClient::processOne(const ChatRequest& req) {
91	    ChatReply reply;
92	    reply.id = req.id;
93	
94	    // Build Ollama /api/chat body. Streaming NDJSON keeps perceived latency
95	    // low (first words appear immediately); keep_alive holds the model in
96	    // memory between conversations. Warm-up requests send no messages, which
97	    // makes Ollama load the model and return at once.
98	    json messages = json::array();
99	    if (!req.internal) {
100	        if (!req.systemPrompt.empty()) {
101	            messages.push_back({{"role", "system"}, {"content", req.systemPrompt}});
102	        }
103	        for (const auto& turn : req.history) {
104	            messages.push_back({{"role", turn.role}, {"content", turn.content}});
105	        }
106	        messages.push_back({{"role", "user"}, {"content", req.userMessage}});
107	    }
108	
109	    json body = {
110	        {"model", config_.model},
111	        {"messages", messages},
112	        {"stream", true},
113	        {"keep_alive", config_.keepAlive},
114	        {"options", {{"temperature", config_.temperature}}},
115	    };
116	
117	    httplib::Client cli(config_.host, config_.port);
118	    cli.set_read_timeout(config_.requestTimeoutSeconds, 0);
119	    cli.set_write_timeout(config_.requestTimeoutSeconds, 0);
120	    cli.set_connection_timeout(5, 0);
121	
122	    int status = 0;
123	    std::string errorBody;   // body bytes of a non-200 response
124	    std::string content;     // accumulated assistant text
125	    std::string streamError; // first error found inside the stream
126	    bool sawDone = false;
127	    StreamAssembler assembler;
128	
129	    // Parses one NDJSON line: append text, surface deltas, note completion.
130	    const auto handleLine = [&](const std::string& line) {
131	        const OllamaChunk chunk = parseOllamaChunk(line);
132	        if (!chunk.error.empty()) {
133	            if (streamError.empty()) streamError = chunk.error;
134	            return;
135	        }
136	        if (!chunk.delta.empty()) {
137	            content += chunk.delta;
138	            if (!req.internal) {
139	                std::lock_guard<std::mutex> lock(replyMutex_);
140	                deltas_.push_back(ChatDelta{req.id, chunk.delta});
141	            }
142	        }
143	        if (chunk.done) sawDone = true;
144	    };
145	
146	    // httplib v0.15 has no streaming Post() overload, so drive a raw Request
147	    // through Client::send with a content receiver.
148	    httplib::Request hreq;
149	    hreq.method = "POST";
150	    hreq.path = "/api/chat";
151	    hreq.set_header("Content-Type", "application/json");
152	    hreq.body = body.dump();
153	    hreq.response_handler = [&](const httplib::Response& response) {
154	        status = response.status;
155	        return true;
156	    };
157	    hreq.content_receiver = [&](const char* data, size_t length, uint64_t, uint64_t) {
158	        if (status != 200) {
159	            errorBody.append(data, length);
160	        } else {
161	            assembler.feed(std::string_view(data, length), handleLine);
162	        }
163	        return true;
164	    };
165	
166	    const httplib::Result result = cli.send(hreq);
167	    if (!result) {
168	        reply.errorMessage = "could not reach Ollama at " + config_.host + ":" +
169	                             std::to_string(config_.port) + " (" + to_string(result.error()) + ")";
170	        return reply;
171	    }
172	
173	    // A final line without a trailing newline still counts.
174	    const std::string tail = assembler.takeRemainder();
175	    if (!tail.empty()) handleLine(tail);
176	
177	    if (status != 200) {
178	        reply.errorMessage = "Ollama returned HTTP " + std::to_string(status) +
179	                             (errorBody.empty() ? "" : ": " + errorBody);
180	        return reply;
181	    }
182	    if (!streamError.empty()) {
183	        reply.errorMessage = streamError;
184	        return reply;
185	    }
186	    if (!sawDone) {
187	        reply.errorMessage = "Ollama stream ended before completion";
188	        return reply;
189	    }
190	    reply.ok = true;
191	    reply.content = std::move(content);
192	    return reply;
193	}
