72	   private:
73	    // Builds the NDJSON payload for the current mode and serves it in small
74	    // fixed-size chunks so lines straddle receive callbacks on the client.
75	    void respondStreaming(httplib::Response& res) {
76	        std::string payload;
77	        {
78	            std::lock_guard<std::mutex> lock(mutex_);
79	            if (mode_ == Mode::ErrorLine) {
80	                payload = "{\"error\":\"model not found\"}\n";
81	            } else {
82	                std::string word;
83	                std::vector<std::string> words;
84	                for (char c : replyText_) {
85	                    word.push_back(c);
86	                    if (c == ' ') {
87	                        words.push_back(word);
88	                        word.clear();
89	                    }
90	                }
91	                if (!word.empty()) words.push_back(word);
92	                for (const auto& w : words) {
93	                    nlohmann::json line = {{"message", {{"role", "assistant"}, {"content", w}}},
94	                                           {"done", false}};
95	                    payload += line.dump() + "\n";
96	                }
97	                if (mode_ == Mode::StreamWords) {
98	                    nlohmann::json final = {{"message", {{"role", "assistant"}, {"content", ""}}},
99	                                            {"done", true}};
100	                    payload += final.dump() + "\n";
101	                }
102	            }
103	        }
104	
105	        // 7-byte chunks guarantee JSON lines split mid-token on the wire.
106	        constexpr std::size_t kChunk = 7;
107	        auto data = std::make_shared<std::string>(std::move(payload));
108	        res.set_chunked_content_provider(
109	            "application/x-ndjson",
110	            [data](std::size_t offset, httplib::DataSink& sink) {
111	                if (offset >= data->size()) {
112	                    sink.done();
113	                    return true;
114	                }
115	                const std::size_t len = std::min(kChunk, data->size() - offset);
116	                sink.write(data->data() + offset, len);
117	                return true;
118	            },
119	            nullptr);
120	    }
121	
122	    httplib::Server server_;
123	    std::thread thread_;
124	    int port_ = 0;
125	    Mode mode_ = Mode::StreamWords;
126	
127	    std::mutex mutex_;
128	    std::string replyText_ = "Hello there, traveler!";
129	    std::vector<std::string> requestBodies_;
130	};
