5	int World::nearestNpcWithin(const Vec3& pos, float radius) const {
6	    int best = -1;
7	    float bestDist = radius;
8	    for (std::size_t i = 0; i < npcs_.size(); ++i) {
9	        const float dist = distanceXZ(pos, npcs_[i].position());
10	        if (dist <= bestDist) {
11	            bestDist = dist;
12	            best = static_cast<int>(i);
13	        }
14	    }
15	    return best;
