15	sf::Color colorFor(TranscriptLine::Kind k) {
16	    switch (k) {
17	        case TranscriptLine::Kind::Player: return sf::Color(180, 220, 255);
18	        case TranscriptLine::Kind::Npc:    return sf::Color(255, 230, 180);
19	        case TranscriptLine::Kind::System: return sf::Color(180, 180, 180);
