24	// Wrap a string to roughly `maxChars` per line. Word-aware: never splits a
25	// word unless the word itself exceeds maxChars. Crude but enough for chat.
26	std::vector<std::string> wrap(const std::string& s, std::size_t maxChars) {
27	    std::vector<std::string> out;
28	    std::string current;
29	    std::string word;
30	    auto flushWord = [&]() {
31	        if (word.empty()) return;
32	        if (current.empty()) {
33	            current = word;
34	        } else if (current.size() + 1 + word.size() <= maxChars) {
35	            current += ' ';
36	            current += word;
37	        } else {
38	            out.push_back(current);
39	            current = word;
40	        }
41	        word.clear();
42	    };
43	    for (char c : s) {
44	        if (c == '\n') {
45	            flushWord();
46	            out.push_back(current);
47	            current.clear();
48	        } else if (c == ' ' || c == '\t') {
49	            flushWord();
50	        } else {
51	            word += c;
52	            if (word.size() > maxChars) {
53	                // Oversized word: hard-break.
54	                if (!current.empty()) {
55	                    out.push_back(current);
56	                    current.clear();
57	                }
58	                out.push_back(word);
59	                word.clear();
60	            }
61	        }
62	    }
63	    flushWord();
64	    if (!current.empty()) out.push_back(current);
65	    return out;
66	}
