71	std::string DialogUI::handleEvent(const sf::Event& event) {
72	    if (event.type == sf::Event::TextEntered && swallowNext_) {
73	        swallowNext_ = false;
74	        return {};
75	    }
76	    if (!inputEnabled_) return {};
77	
78	    if (event.type == sf::Event::TextEntered) {
79	        const auto unicode = event.text.unicode;
80	        if (unicode == 8) {  // backspace
81	            if (!input_.empty()) input_.pop_back();
82	        } else if (unicode == 13 || unicode == 10) {  // enter
83	            // Handled in KeyPressed below to avoid double-fire on some platforms.
84	        } else if (unicode >= 32 && unicode < 127) {
85	            input_ += static_cast<char>(unicode);
86	        }
87	        return {};
88	    }
89	
90	    if (event.type == sf::Event::KeyPressed &&
91	        (event.key.code == sf::Keyboard::Enter || event.key.code == sf::Keyboard::Return)) {
92	        if (input_.empty()) return {};
93	        std::string submitted = std::move(input_);
94	        input_.clear();
95	        return submitted;
96	    }
97	    return {};
98	}
