141	void DialogUI::render(sf::RenderTarget& target) const {
142	    const sf::Vector2u sz = target.getSize();
143	    const float w = static_cast<float>(sz.x);
144	    const float h = static_cast<float>(sz.y);
145	
146	    const float transcriptBottom = h - kInputHeight - kPadding;
147	    const std::size_t wrapChars = std::max<std::size_t>(20, static_cast<std::size_t>((w - 2 * kPadding) / 9.0f));
148	
149	    // Collect wrapped, colored lines from newest backward until we run out of
150	    // vertical space. Then render them in chronological order.
151	    struct RenderedLine { std::string text; sf::Color color; };
152	    std::vector<RenderedLine> rendered;
153	    float used = 0.f;
154	    const float available = transcriptBottom - kPadding;
155	
156	    if (streaming_ && !streamingText_.empty()) {
157	        // Live, partially-streamed NPC line with a cursor.
158	        const std::string prefix = streamingSpeaker_.empty() ? "" : streamingSpeaker_ + ": ";
159	        auto wrapped = wrap(prefix + streamingText_ + "_", wrapChars);
160	        for (auto wi = wrapped.rbegin(); wi != wrapped.rend(); ++wi) {
161	            if (used + kLineHeight > available) break;
162	            rendered.push_back({*wi, colorFor(TranscriptLine::Kind::Npc)});
163	            used += kLineHeight;
164	        }
165	    } else if (thinking_ || streaming_) {
166	        const std::string speaker = streaming_ ? streamingSpeaker_ : thinkingSpeaker_;
167	        std::string indicator = "... " + (speaker.empty() ? std::string("(thinking)")
168	                                                          : speaker + " is thinking...");
169	        rendered.push_back({indicator, sf::Color(140, 140, 140)});
170	        used += kLineHeight;
171	    }
172	
173	    for (auto it = transcript_.rbegin(); it != transcript_.rend(); ++it) {
174	        const auto& line = *it;
175	        std::string prefix = line.speaker.empty() ? "" : line.speaker + ": ";
176	        auto wrapped = wrap(prefix + line.text, wrapChars);
177	        // Push in reverse so chronological order is preserved once we reverse the whole vector.
178	        for (auto wi = wrapped.rbegin(); wi != wrapped.rend(); ++wi) {
179	            if (used + kLineHeight > available) break;
180	            rendered.push_back({*wi, colorFor(line.kind)});
181	            used += kLineHeight;
182	        }
183	        if (used + kLineHeight > available) break;
184	    }
185	
186	    std::reverse(rendered.begin(), rendered.end());
187	
188	    float y = transcriptBottom - static_cast<float>(rendered.size()) * kLineHeight;
189	    for (const auto& rl : rendered) {
190	        sf::Text t(rl.text, font_, kFontSize);
191	        t.setFillColor(rl.color);
192	        t.setPosition(kPadding, y);
193	        target.draw(t);
194	        y += kLineHeight;
195	    }
196	
197	    // Input box.
198	    sf::RectangleShape box(sf::Vector2f(w - 2 * kPadding, kInputHeight));
199	    box.setPosition(kPadding, h - kInputHeight - kPadding * 0.5f);
200	    box.setFillColor(sf::Color(30, 30, 36));
201	    box.setOutlineColor(inputEnabled_ ? sf::Color(120, 160, 220) : sf::Color(70, 70, 70));
202	    box.setOutlineThickness(2.f);
203	    target.draw(box);
204	
205	    sf::Text prompt(std::string("> ") + input_ + (inputEnabled_ ? "_" : ""), font_, kFontSize);
206	    prompt.setFillColor(inputEnabled_ ? sf::Color::White : sf::Color(120, 120, 120));
207	    prompt.setPosition(kPadding + 10.f, h - kInputHeight - kPadding * 0.5f + 12.f);
208	    target.draw(prompt);
209	}
