68	// Unit forward vector on the ground plane for a yaw in degrees.
69	Vec3 flatForward(float yawDeg) {
70	    return normalize(Vec3{std::sin(degToRad(yawDeg)), 0.f, std::cos(degToRad(yawDeg))});
71	}
72	
73	// Ground-plane right vector for a yaw in degrees.
74	Vec3 flatRight(float yawDeg) {
75	    const Vec3 f = flatForward(yawDeg);
76	    return Vec3{f.z, 0.f, -f.x};
77	}
