79	// Re-centers the OS cursor so relative mouse-look deltas keep working.
80	void centerMouse(sf::RenderWindow& window) {
81	    sf::Mouse::setPosition(sf::Vector2i(static_cast<int>(window.getSize().x / 2),
82	                                        static_cast<int>(window.getSize().y / 2)),
83	                           window);
84	}
85	
86	// Applies one frame of mouse look to the camera and re-centers the cursor.
87	void handleMouseLook(sf::RenderWindow& window, CameraPose& camera) {
88	    const sf::Vector2i center(static_cast<int>(window.getSize().x / 2),
89	                              static_cast<int>(window.getSize().y / 2));
90	    const sf::Vector2i delta = sf::Mouse::getPosition(window) - center;
91	    camera.yawDeg += static_cast<float>(delta.x) * kMouseSensitivity;
92	    camera.pitchDeg = clampf(camera.pitchDeg - static_cast<float>(delta.y) * kMouseSensitivity,
93	                             -kMaxPitchDeg, kMaxPitchDeg);
94	    if (window.hasFocus()) centerMouse(window);
95	}
