97	// Draws `str` centered horizontally at height `y`, with a dark backdrop bar.
98	void drawCenteredHudText(sf::RenderWindow& window, const sf::Font& font,
99	                         const std::string& str, unsigned size, float y) {
100	    sf::Text text(str, font, size);
101	    const sf::FloatRect bounds = text.getLocalBounds();
102	    const float x = (static_cast<float>(window.getSize().x) - bounds.width) * 0.5f;
103	
104	    sf::RectangleShape backdrop(sf::Vector2f(bounds.width + 24.f, bounds.height + 16.f));
105	    backdrop.setPosition(x - 12.f, y - 6.f);
106	    backdrop.setFillColor(sf::Color(10, 14, 22, 170));
107	    window.draw(backdrop);
108	
109	    text.setPosition(x, y);
110	    text.setFillColor(sf::Color::White);
111	    window.draw(text);
112	}
