148	    settings.majorVersion = 2;
149	    settings.minorVersion = 1;
150	    sf::RenderWindow window(sf::VideoMode(1280, 720), "LLM NPC City", sf::Style::Default, settings);
151	    window.setVerticalSyncEnabled(true);
152	    window.setActive(true);
153	
154	    sf::Font font;
155	    const fs::path fontPath = findSystemFont();
156	    if (fontPath.empty() || !font.loadFromFile(fontPath.string())) {
157	        std::cerr << "[llm_npc] no system font found; UI cannot render text.\n";
158	        return 1;
159	    }
160	
161	    Renderer3D renderer;
162	    renderer.init();
163	
164	    DialogUI dialog(font);
165	    DialogueSession session;
166	    Menu menu(bindings, bindingsPath);
167	    // Late replies for conversations the player already walked away from
168	    // still need to reach the right NPC's history.
169	    std::unordered_map<std::uint64_t, int> pendingRoutes;
170	
171	    AppMode mode = AppMode::Playing;
172	    CameraPose camera;
173	    camera.position = Vec3{0.f, 0.f, 24.f};  // plaza south edge, facing the cart
174	    window.setMouseCursorVisible(false);
175	    centerMouse(window);
176	
177	    int nearbyNpc = -1;
178	    sf::Clock frameClock;
179	    while (window.isOpen()) {
180	        sf::Event event{};
181	        while (window.pollEvent(event)) {
182	            if (event.type == sf::Event::Closed) window.close();
183	            if (event.type == sf::Event::GainedFocus && mode == AppMode::Playing) centerMouse(window);
184	
185	            if (mode == AppMode::Playing && event.type == sf::Event::KeyPressed) {
186	                const bool menuKey = event.key.code == keyFromName(bindings.key(Action::OpenMenu)) ||
187	                                     event.key.code == sf::Keyboard::Escape;
188	                if (menuKey) {
189	                    menu.open();
190	                    mode = AppMode::Menu;
191	                    window.setMouseCursorVisible(true);
192	                } else if (event.key.code == keyFromName(bindings.key(Action::Talk)) && nearbyNpc >= 0) {
193	                    session.open(nearbyNpc);
194	                    const Npc& npc = world.npcs()[static_cast<std::size_t>(nearbyNpc)];
195	                    dialog.reset();
196	                    dialog.setInputEnabled(true);
197	                    dialog.swallowNextTextEntered();
198	                    dialog.appendLine({TranscriptLine::Kind::System, "",
199	                                       "You are talking to " + npc.persona().name + " (" +
200	                                           npc.persona().role + "). Enter sends, Esc leaves."});
201	                    mode = AppMode::Dialogue;
202	                    window.setMouseCursorVisible(true);
203	                }
204	                continue;
205	            }
206	
207	            if (mode == AppMode::Dialogue) {
208	                if (event.type == sf::Event::KeyPressed && event.key.code == sf::Keyboard::Escape) {
209	                    session.close();
210	                    dialog.endStreaming();
211	                    mode = AppMode::Playing;
212	                    window.setMouseCursorVisible(false);
213	                    centerMouse(window);
214	                    continue;
215	                }
216	                const std::string submitted = dialog.handleEvent(event);
217	                if (!submitted.empty() && session.isOpen()) {
218	                    Npc& npc = world.npcs()[static_cast<std::size_t>(session.npcIndex())];
219	                    if (!npc.waiting()) {
220	                        dialog.appendLine({TranscriptLine::Kind::Player, "You", submitted});
221	                        const std::uint64_t id = npc.ask(submitted);
222	                        session.submitted(id);
223	                        pendingRoutes[id] = session.npcIndex();
224	                        dialog.beginStreaming(npc.persona().name);
225	                        dialog.setInputEnabled(false);
226	                    }
227	                }
228	                continue;
229	            }
230	
231	            if (mode == AppMode::Menu) {
232	                switch (menu.handleEvent(event, window)) {
233	                    case MenuResult::Resume:
234	                        mode = AppMode::Playing;
235	                        window.setMouseCursorVisible(false);
236	                        centerMouse(window);
237	                        break;
238	                    case MenuResult::Quit:
239	                        window.close();
240	                        break;
241	                    case MenuResult::None:
242	                        break;
243	                }
244	            }
245	        }
246	        if (!window.isOpen()) break;
247	
248	        const float dt = std::min(0.03f, frameClock.restart().asSeconds());
249	
250	        if (mode == AppMode::Playing) {
251	            if (window.hasFocus()) handleMouseLook(window, camera);
252	
253	            Vec3 wish{};
254	            if (isActionPressed(bindings, Action::MoveForward)) wish += flatForward(camera.yawDeg);
255	            if (isActionPressed(bindings, Action::MoveBackward)) wish += flatForward(camera.yawDeg) * -1.f;
256	            if (isActionPressed(bindings, Action::StrafeRight)) wish += flatRight(camera.yawDeg);
257	            if (isActionPressed(bindings, Action::StrafeLeft)) wish += flatRight(camera.yawDeg) * -1.f;
258	            wish = normalize(wish);
259	            const Vec3 target = camera.position + wish * (kWalkSpeed * dt);
260	            camera.position = world.city().resolveMovement(camera.position, target, kPlayerRadius);
261	        } else if (mode == AppMode::Menu) {
262	            menu.update(dt);
263	        }
264	
265	        nearbyNpc = world.nearestNpcWithin(camera.position, kTalkRadius);
266	
267	        // Streamed fragments for the open conversation appear immediately.
268	        for (const auto& delta : client.drainDeltas()) {
269	            if (session.deltaArrived(delta.id, delta.text)) {
270	                dialog.appendStreamingDelta(delta.text);
271	            }
272	        }
273	
274	        // Completed replies land in NPC history even after the dialog closed.
275	        for (const auto& reply : client.drainReplies()) {
276	            const auto route = pendingRoutes.find(reply.id);
277	            if (route == pendingRoutes.end()) continue;
278	            Npc& npc = world.npcs()[static_cast<std::size_t>(route->second)];
279	            const auto text = npc.onReplyArrived(reply);
280	            pendingRoutes.erase(route);
281	
282	            if (session.replyArrived(reply.id, reply.ok)) {
283	                dialog.endStreaming();
284	                if (text) {
285	                    dialog.appendLine({TranscriptLine::Kind::Npc, npc.persona().name, *text});
286	                } else {
287	                    dialog.appendLine({TranscriptLine::Kind::System, "",
288	                                       "[" + npc.persona().name + " seems distracted: " +
289	                                           reply.errorMessage + "]"});
290	                }
291	                dialog.setInputEnabled(true);
292	            }
293	        }
294	
295	        // ---- 3D pass ----
296	        renderer.beginFrame(window, camera);
297	        renderer.drawCity(world.city());
298	        for (std::size_t i = 0; i < world.npcs().size(); ++i) {
299	            const Npc& npc = world.npcs()[i];
300	            renderer.drawNpc(NpcVisual{npc.position(), npc.facingDeg(), static_cast<int>(i)});
301	        }
302	
303	        // ---- SFML overlay pass ----
304	        window.pushGLStates();
305	
306	        for (const Npc& npc : world.npcs()) {
307	            if (distanceXZ(camera.position, npc.position()) > kNameplateRange) continue;
308	            sf::Vector2f screen;
309	            if (!renderer.worldToScreen(npc.position() + Vec3{0.f, 2.15f, 0.f}, window, screen)) continue;
310	            sf::Text tag(npc.persona().name, font, 14);
311	            const sf::FloatRect bounds = tag.getLocalBounds();
312	            tag.setPosition(screen.x - bounds.width * 0.5f, screen.y - bounds.height);
313	            tag.setOutlineThickness(2.f);
314	            tag.setOutlineColor(sf::Color(0, 0, 0, 200));
315	            tag.setFillColor(sf::Color::White);
316	            window.draw(tag);
317	        }
318	
319	        if (mode == AppMode::Playing) {
320	            if (nearbyNpc >= 0) {
321	                const Npc& npc = world.npcs()[static_cast<std::size_t>(nearbyNpc)];
322	                drawCenteredHudText(window, font,
323	                                    "[" + bindings.key(Action::Talk) + "] Talk to " + npc.persona().name,
324	                                    20, static_cast<float>(window.getSize().y) - 84.f);
325	            }
326	            // Crosshair dot.
327	            sf::CircleShape dot(2.f);
328	            dot.setOrigin(2.f, 2.f);
329	            dot.setPosition(static_cast<float>(window.getSize().x) * 0.5f,
330	                            static_cast<float>(window.getSize().y) * 0.5f);
331	            dot.setFillColor(sf::Color(255, 255, 255, 200));
332	            window.draw(dot);
333	        } else if (mode == AppMode::Dialogue) {
334	            sf::RectangleShape dim(sf::Vector2f(static_cast<float>(window.getSize().x),
335	                                                static_cast<float>(window.getSize().y)));
336	            dim.setFillColor(sf::Color(8, 10, 16, 150));
337	            window.draw(dim);
338	            dialog.render(window);
339	        } else {
340	            menu.render(window, font);
341	        }
342	
343	        window.popGLStates();
344	        window.display();
345	    }
346	    return 0;
347	}
