12	// Name <-> key pairs for every key the rebinding UI accepts. Letters and
13	// digits are appended programmatically in buildTable().
14	const std::vector<std::pair<std::string, sf::Keyboard::Key>>& table() {
15	    static const std::vector<std::pair<std::string, sf::Keyboard::Key>> entries = [] {
16	        std::vector<std::pair<std::string, sf::Keyboard::Key>> t = {
17	            {"Escape", sf::Keyboard::Escape},
18	            {"Space", sf::Keyboard::Space},
19	            {"Enter", sf::Keyboard::Enter},
20	            {"Tab", sf::Keyboard::Tab},
21	            {"Backspace", sf::Keyboard::Backspace},
22	            {"LShift", sf::Keyboard::LShift},
23	            {"RShift", sf::Keyboard::RShift},
24	            {"LControl", sf::Keyboard::LControl},
25	            {"RControl", sf::Keyboard::RControl},
26	            {"LAlt", sf::Keyboard::LAlt},
27	            {"RAlt", sf::Keyboard::RAlt},
28	            {"Left", sf::Keyboard::Left},
29	            {"Right", sf::Keyboard::Right},
30	            {"Up", sf::Keyboard::Up},
31	            {"Down", sf::Keyboard::Down},
32	            {"Home", sf::Keyboard::Home},
33	            {"End", sf::Keyboard::End},
34	            {"PageUp", sf::Keyboard::PageUp},
35	            {"PageDown", sf::Keyboard::PageDown},
36	            {"Insert", sf::Keyboard::Insert},
37	            {"Delete", sf::Keyboard::Delete},
38	            {"Comma", sf::Keyboard::Comma},
39	            {"Period", sf::Keyboard::Period},
40	            {"Slash", sf::Keyboard::Slash},
41	            {"Semicolon", sf::Keyboard::Semicolon},
42	            {"Quote", sf::Keyboard::Quote},
43	            {"LBracket", sf::Keyboard::LBracket},
44	            {"RBracket", sf::Keyboard::RBracket},
45	            {"Hyphen", sf::Keyboard::Hyphen},
46	            {"Equal", sf::Keyboard::Equal},
47	        };
48	        for (int i = 0; i < 26; ++i) {
49	            t.emplace_back(std::string(1, static_cast<char>('A' + i)),
50	                           static_cast<sf::Keyboard::Key>(static_cast<int>(sf::Keyboard::A) + i));
51	        }
52	        for (int i = 0; i < 10; ++i) {
53	            t.emplace_back(std::string(1, static_cast<char>('0' + i)),
54	                           static_cast<sf::Keyboard::Key>(static_cast<int>(sf::Keyboard::Num0) + i));
55	        }
56	        for (int i = 0; i < 12; ++i) {
57	            t.emplace_back("F" + std::to_string(i + 1),
58	                           static_cast<sf::Keyboard::Key>(static_cast<int>(sf::Keyboard::F1) + i));
59	        }
60	        return t;
61	    }();
62	    return entries;
63	}
64	
65	}  // namespace
66	
67	sf::Keyboard::Key keyFromName(const std::string& name) {
68	    std::string canon = name;
69	    if (canon.size() == 1) canon[0] = static_cast<char>(std::toupper(canon[0]));
70	    for (const auto& [entryName, key] : table()) {
71	        if (entryName == canon) return key;
72	    }
73	    return sf::Keyboard::Unknown;
74	}
75	
76	std::string keyNameOf(sf::Keyboard::Key key) {
77	    for (const auto& [entryName, entryKey] : table()) {
78	        if (entryKey == key) return entryName;
79	    }
80	    return {};
81	}
82	
83	bool isActionPressed(const KeyBindings& bindings, Action action) {
84	    const sf::Keyboard::Key key = keyFromName(bindings.key(action));
85	    return key != sf::Keyboard::Unknown && sf::Keyboard::isKeyPressed(key);
86	}
