14	// What the main loop should do after the menu handled an event.
15	enum class MenuResult {
16	    None,    // keep showing the menu
17	    Resume,  // close the menu and return to the game
18	    Quit,    // close the window
19	};
20	
21	// Mouse-driven pause menu: Resume / Controls / Quit on the main page, and a
22	// Controls page where clicking a key chip arms capture of the next key press.
23	// Rebinds use KeyBindings swap semantics and are saved to disk immediately.
24	class Menu {
25	   public:
26	    // `bindings` is shared with the main loop; `savePath` is where every
27	    // accepted rebind is persisted.
28	    Menu(KeyBindings& bindings, std::filesystem::path savePath);
29	
30	    // Resets to the main page (called when the menu is opened).
31	    void open();
32	
33	    // True while the Controls page is waiting for a key press to bind.
34	    bool capturingKey() const { return awaiting_.has_value(); }
35	
36	    // Routes one SFML event (mouse move/click, key press during capture).
37	    // Escape closes the menu from the main page, backs out of the Controls
38	    // page, or cancels an armed capture — in that priority order.
39	    MenuResult handleEvent(const sf::Event& event, const sf::RenderWindow& window);
40	
41	    // Ages the transient toast message.
42	    void update(float dt);
43	
44	    // Draws the menu; call between pushGLStates/popGLStates.
45	    void render(sf::RenderWindow& window, const sf::Font& font) const;
46	
47	   private:
48	    enum class Page { Main, Controls };
49	
50	    // A clickable rectangle paired with what clicking it means.
51	    struct Hit {
52	        sf::FloatRect rect;
53	        int id = 0;  // page-specific meaning, see layout helpers
54	    };
55	
56	    KeyBindings& bindings_;
57	    std::filesystem::path savePath_;
58	    Page page_ = Page::Main;
59	    std::optional<Action> awaiting_;
60	    sf::Vector2f mouse_{};
61	    std::string toast_;
62	    float toastLeft_ = 0.f;
63	
64	    // Clickable areas for the current page, derived from the window size so
65	    // render() and handleEvent() always agree.
66	    std::vector<Hit> layout(const sf::RenderWindow& window) const;
67	
68	    // Applies a captured key press to the armed action; announces swaps.
69	    void applyCapture(sf::Keyboard::Key key);
70	
71	    // Shows a short status message under the controls list.
72	    void showToast(std::string text);
73	};
