11	// Ids used by layout()/handleEvent() to identify what was clicked.
12	constexpr int kIdResume = 0;
13	constexpr int kIdControls = 1;
14	constexpr int kIdQuit = 2;
15	constexpr int kIdBack = 100;
16	// Controls-page chips use ids [kIdChipBase, kIdChipBase + kActionCount).
17	constexpr int kIdChipBase = 200;
18	
19	constexpr float kToastSeconds = 3.f;
20	
21	// Builds a ready-to-draw text object anchored at `pos`.
22	sf::Text makeText(const sf::Font& font, const std::string& str, unsigned size,
23	                  sf::Vector2f pos, sf::Color color) {
24	    sf::Text text(str, font, size);
25	    text.setPosition(pos);
26	    text.setFillColor(color);
27	    return text;
28	}
29	
30	// Draws `str` horizontally centered inside `rect`.
31	void drawCentered(sf::RenderWindow& window, const sf::Font& font, const std::string& str,
32	                  unsigned size, const sf::FloatRect& rect, sf::Color color) {
33	    sf::Text text(str, font, size);
34	    const sf::FloatRect bounds = text.getLocalBounds();
35	    text.setPosition(rect.left + (rect.width - bounds.width) * 0.5f - bounds.left,
36	                     rect.top + (rect.height - bounds.height) * 0.5f - bounds.top);
37	    text.setFillColor(color);
38	    window.draw(text);
39	}
