43	Menu::Menu(KeyBindings& bindings, std::filesystem::path savePath)
44	    : bindings_(bindings), savePath_(std::move(savePath)) {}
45	
46	void Menu::open() {
47	    page_ = Page::Main;
48	    awaiting_.reset();
49	    toast_.clear();
50	    toastLeft_ = 0.f;
51	}
