53	std::vector<Menu::Hit> Menu::layout(const sf::RenderWindow& window) const {
54	    const float w = static_cast<float>(window.getSize().x);
55	    const float h = static_cast<float>(window.getSize().y);
56	    std::vector<Hit> hits;
57	
58	    if (page_ == Page::Main) {
59	        const sf::Vector2f size(320.f, 52.f);
60	        const float x = (w - size.x) * 0.5f;
61	        float y = h * 0.5f - 110.f;
62	        for (int id : {kIdResume, kIdControls, kIdQuit}) {
63	            hits.push_back({sf::FloatRect(x, y, size.x, size.y), id});
64	            y += 72.f;
65	        }
66	    } else {
67	        float y = h * 0.24f;
68	        for (std::size_t i = 0; i < kActionCount; ++i) {
69	            hits.push_back({sf::FloatRect(w * 0.5f + 90.f, y, 180.f, 40.f),
70	                            kIdChipBase + static_cast<int>(i)});
71	            y += 52.f;
72	        }
73	        hits.push_back({sf::FloatRect((w - 320.f) * 0.5f, y + 28.f, 320.f, 52.f), kIdBack});
74	    }
75	    return hits;
76	}
