78	MenuResult Menu::handleEvent(const sf::Event& event, const sf::RenderWindow& window) {
79	    if (event.type == sf::Event::MouseMoved) {
80	        mouse_ = {static_cast<float>(event.mouseMove.x), static_cast<float>(event.mouseMove.y)};
81	        return MenuResult::None;
82	    }
83	
84	    if (event.type == sf::Event::KeyPressed) {
85	        if (awaiting_) {
86	            if (event.key.code == sf::Keyboard::Escape) {
87	                awaiting_.reset();
88	                showToast("Rebind cancelled");
89	            } else {
90	                applyCapture(event.key.code);
91	            }
92	            return MenuResult::None;
93	        }
94	        if (event.key.code == sf::Keyboard::Escape) {
95	            if (page_ == Page::Controls) {
96	                page_ = Page::Main;
97	                return MenuResult::None;
98	            }
99	            return MenuResult::Resume;
100	        }
101	        return MenuResult::None;
102	    }
103	
104	    if (event.type == sf::Event::MouseButtonPressed && event.mouseButton.button == sf::Mouse::Left) {
105	        const sf::Vector2f click(static_cast<float>(event.mouseButton.x),
106	                                 static_cast<float>(event.mouseButton.y));
107	        for (const Hit& hit : layout(window)) {
108	            if (!hit.rect.contains(click)) continue;
109	            if (hit.id == kIdResume) return MenuResult::Resume;
110	            if (hit.id == kIdQuit) return MenuResult::Quit;
111	            if (hit.id == kIdControls) {
112	                page_ = Page::Controls;
113	                return MenuResult::None;
114	            }
115	            if (hit.id == kIdBack) {
116	                awaiting_.reset();
117	                page_ = Page::Main;
118	                return MenuResult::None;
119	            }
120	            if (hit.id >= kIdChipBase && hit.id < kIdChipBase + static_cast<int>(kActionCount)) {
121	                awaiting_ = static_cast<Action>(hit.id - kIdChipBase);
122	                toast_.clear();
123	                return MenuResult::None;
124	            }
125	        }
126	        // Clicking empty space cancels an armed capture.
127	        awaiting_.reset();
128	        return MenuResult::None;
129	    }
130	
131	    return MenuResult::None;
132	}
133	
134	void Menu::applyCapture(sf::Keyboard::Key key) {
135	    const std::string name = keyNameOf(key);
136	    if (name.empty()) {
137	        showToast("That key can't be bound");
138	        return;
139	    }
140	    const Action action = *awaiting_;
141	    awaiting_.reset();
142	    const std::optional<Action> displaced = bindings_.rebind(action, name);
143	    if (displaced) {
144	        showToast(std::string("Swapped keys with \"") + KeyBindings::actionLabel(*displaced) + "\"");
145	    } else {
146	        showToast(std::string(KeyBindings::actionLabel(action)) + " is now " + name);
147	    }
148	    if (!bindings_.save(savePath_)) {
149	        showToast("Warning: could not save key bindings");
150	    }
151	}
152	
153	void Menu::showToast(std::string text) {
154	    toast_ = std::move(text);
155	    toastLeft_ = kToastSeconds;
156	}
157	
158	void Menu::update(float dt) {
159	    if (toastLeft_ > 0.f) {
160	        toastLeft_ -= dt;
161	        if (toastLeft_ <= 0.f) toast_.clear();
162	    }
163	}
