165	void Menu::render(sf::RenderWindow& window, const sf::Font& font) const {
166	    const float w = static_cast<float>(window.getSize().x);
167	    const float h = static_cast<float>(window.getSize().y);
168	
169	    sf::RectangleShape dim(sf::Vector2f(w, h));
170	    dim.setFillColor(sf::Color(8, 10, 16, 170));
171	    window.draw(dim);
172	
173	    const char* title = page_ == Page::Main ? "Paused" : "Controls";
174	    sf::Text titleText = makeText(font, title, 40, {0.f, h * 0.12f}, sf::Color(235, 240, 250));
175	    titleText.setPosition((w - titleText.getLocalBounds().width) * 0.5f, h * 0.12f);
176	    window.draw(titleText);
177	
178	    for (const Hit& hit : layout(window)) {
179	        const bool hover = hit.rect.contains(mouse_);
180	        const bool isChip = hit.id >= kIdChipBase && hit.id < kIdChipBase + static_cast<int>(kActionCount);
181	
182	        sf::RectangleShape box(sf::Vector2f(hit.rect.width, hit.rect.height));
183	        box.setPosition(hit.rect.left, hit.rect.top);
184	        box.setFillColor(hover ? sf::Color(60, 90, 140, 230) : sf::Color(30, 40, 60, 215));
185	        box.setOutlineThickness(2.f);
186	        box.setOutlineColor(sf::Color(110, 160, 220, 200));
187	        window.draw(box);
188	
189	        std::string label;
190	        if (hit.id == kIdResume) label = "Resume";
191	        else if (hit.id == kIdControls) label = "Controls";
192	        else if (hit.id == kIdQuit) label = "Quit";
193	        else if (hit.id == kIdBack) label = "Back";
194	        else if (isChip) {
195	            const Action action = static_cast<Action>(hit.id - kIdChipBase);
196	            const bool armed = awaiting_ && *awaiting_ == action;
197	            label = armed ? "press a key..." : bindings_.key(action);
198	            if (label.empty()) label = "(unbound)";
199	
200	            const sf::Text rowLabel = makeText(font, KeyBindings::actionLabel(action), 22,
201	                                               {w * 0.5f - 280.f, hit.rect.top + 6.f},
202	                                               sf::Color(225, 230, 240));
203	            window.draw(rowLabel);
204	        }
205	        drawCentered(window, font, label, isChip ? 20 : 24, hit.rect, sf::Color::White);
206	    }
207	
208	    if (page_ == Page::Controls) {
209	        const sf::Text hint = makeText(font, "Click a key, then press the new key. Esc cancels.", 18,
210	                                       {0.f, 0.f}, sf::Color(170, 180, 200));
211	        sf::Text centered = hint;
212	        centered.setPosition((w - hint.getLocalBounds().width) * 0.5f, h * 0.24f - 40.f);
213	        window.draw(centered);
214	    }
215	
216	    if (!toast_.empty()) {
217	        sf::Text toast = makeText(font, toast_, 20, {0.f, 0.f}, sf::Color(255, 225, 130));
218	        toast.setPosition((w - toast.getLocalBounds().width) * 0.5f, h * 0.88f);
219	        window.draw(toast);
220	    }
221	}
