60	    // true and fills `out` with pixel coordinates when the point is in front
61	    // of the camera; false when it is behind (the caller should skip drawing).
62	    bool worldToScreen(const Vec3& world, const sf::RenderWindow& window, sf::Vector2f& out) const;
