13	// Uploads a square RGBA pixel buffer as a repeating, linearly filtered texture.
14	GLuint createTexture(const std::vector<std::uint8_t>& pixels, int size) {
15	    GLuint texture = 0;
16	    glGenTextures(1, &texture);
17	    glBindTexture(GL_TEXTURE_2D, texture);
18	    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
19	    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
20	    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_REPEAT);
21	    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_REPEAT);
22	    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, size, size, 0, GL_RGBA, GL_UNSIGNED_BYTE, pixels.data());
23	    return texture;
24	}
25	
26	// Procedural checkerboard texture of `cells` x `cells` squares in two colors.
27	GLuint makeCheckerTexture(const sf::Color& a, const sf::Color& b, int cells) {
28	    constexpr int size = 64;
29	    std::vector<std::uint8_t> pixels(size * size * 4, 255);
30	    for (int y = 0; y < size; ++y) {
31	        for (int x = 0; x < size; ++x) {
32	            const int cellX = (x * cells) / size;
33	            const int cellY = (y * cells) / size;
34	            const sf::Color color = ((cellX + cellY) % 2 == 0) ? a : b;
35	            const int i = (y * size + x) * 4;
36	            pixels[i + 0] = color.r;
37	            pixels[i + 1] = color.g;
38	            pixels[i + 2] = color.b;
39	        }
40	    }
41	    return createTexture(pixels, size);
42	}
43	
44	// Procedural vertical-stripe texture: alternating 8-pixel columns.
45	GLuint makeStripeTexture(const sf::Color& base, const sf::Color& stripe) {
46	    constexpr int size = 64;
47	    std::vector<std::uint8_t> pixels(size * size * 4, 255);
48	    for (int y = 0; y < size; ++y) {
49	        for (int x = 0; x < size; ++x) {
50	            const sf::Color color = ((x / 8) % 2 == 0) ? stripe : base;
51	            const int i = (y * size + x) * 4;
52	            pixels[i + 0] = color.r;
53	            pixels[i + 1] = color.g;
54	            pixels[i + 2] = color.b;
55	        }
56	    }
57	    return createTexture(pixels, size);
58	}
59	
60	// Procedural brick texture: running-bond courses with mortar lines.
61	GLuint makeBrickTexture(const sf::Color& brick, const sf::Color& mortar) {
62	    constexpr int size = 64;
63	    constexpr int courseH = 8;
64	    constexpr int brickW = 16;
65	    std::vector<std::uint8_t> pixels(size * size * 4, 255);
66	    for (int y = 0; y < size; ++y) {
67	        const int course = y / courseH;
68	        const int offset = (course % 2 == 0) ? 0 : brickW / 2;
69	        for (int x = 0; x < size; ++x) {
70	            const bool mortarRow = (y % courseH) == 0;
71	            const bool mortarCol = ((x + offset) % brickW) == 0;
72	            const sf::Color color = (mortarRow || mortarCol) ? mortar : brick;
73	            const int i = (y * size + x) * 4;
74	            pixels[i + 0] = color.r;
75	            pixels[i + 1] = color.g;
76	            pixels[i + 2] = color.b;
77	        }
78	    }
79	    return createTexture(pixels, size);
80	}
