82	// Sets the GL color from an opaque SFML color.
83	void setColor(const sf::Color& color) {
84	    glColor3f(color.r / 255.0f, color.g / 255.0f, color.b / 255.0f);
85	}
86	
87	// Emits one textured vertex.
88	void vertexTextured(const Vec3& v, float u, float t) {
89	    glTexCoord2f(u, t);
90	    glVertex3f(v.x, v.y, v.z);
91	}
92	
93	// Emits a textured quad a-b-c-d with a face normal; must be inside
94	// glBegin(GL_QUADS).
95	void drawTexturedQuad(const Vec3& a, const Vec3& b, const Vec3& c, const Vec3& d, float tileU, float tileV) {
96	    const Vec3 n = normalize(cross(b - a, c - a));
97	    glNormal3f(n.x, n.y, n.z);
98	    vertexTextured(a, 0.0f, 0.0f);
99	    vertexTextured(b, tileU, 0.0f);
100	    vertexTextured(c, tileU, tileV);
101	    vertexTextured(d, 0.0f, tileV);
102	}
103	
104	// Draws an axis-aligned textured box (top + four sides; the bottom is never
105	// visible from a first-person camera on the ground).
106	void drawTexturedBox(const Vec3& center, float halfX, float halfY, float halfZ,
107	                     GLuint texture, const sf::Color& tint, float tileScale) {
108	    const Vec3 lbf{center.x - halfX, center.y - halfY, center.z - halfZ};
109	    const Vec3 rbf{center.x + halfX, center.y - halfY, center.z - halfZ};
110	    const Vec3 rbb{center.x + halfX, center.y - halfY, center.z + halfZ};
111	    const Vec3 lbb{center.x - halfX, center.y - halfY, center.z + halfZ};
112	    const Vec3 ltf{center.x - halfX, center.y + halfY, center.z - halfZ};
113	    const Vec3 rtf{center.x + halfX, center.y + halfY, center.z - halfZ};
114	    const Vec3 rtb{center.x + halfX, center.y + halfY, center.z + halfZ};
115	    const Vec3 ltb{center.x - halfX, center.y + halfY, center.z + halfZ};
116	
117	    glBindTexture(GL_TEXTURE_2D, texture);
118	    setColor(tint);
119	    glBegin(GL_QUADS);
120	    drawTexturedQuad(ltf, rtf, rtb, ltb, tileScale, tileScale);
121	    drawTexturedQuad(lbf, rbf, rtf, ltf, tileScale, tileScale);
122	    drawTexturedQuad(rbf, rbb, rtb, rtf, tileScale, tileScale);
123	    drawTexturedQuad(rbb, lbb, ltb, rtb, tileScale, tileScale);
124	    drawTexturedQuad(lbb, lbf, ltf, ltb, tileScale, tileScale);
125	    glEnd();
126	}
127	
128	// Draws a vertical textured cylinder (caps + wall) centered at `center`.
129	void drawTexturedCylinder(const Vec3& center, float radius, float halfHeight,
130	                          int segments, GLuint texture, const sf::Color& tint) {
131	    glBindTexture(GL_TEXTURE_2D, texture);
132	    setColor(tint);
133	
134	    glBegin(GL_TRIANGLE_FAN);
135	    glNormal3f(0.0f, 1.0f, 0.0f);
136	    vertexTextured(Vec3{center.x, center.y + halfHeight, center.z}, 0.5f, 0.5f);
137	    for (int i = 0; i <= segments; ++i) {
138	        const float angle = (2.0f * kPi * static_cast<float>(i)) / static_cast<float>(segments);
139	        vertexTextured(Vec3{center.x + std::cos(angle) * radius, center.y + halfHeight,
140	                            center.z + std::sin(angle) * radius},
141	                       0.5f + std::cos(angle) * 0.5f, 0.5f + std::sin(angle) * 0.5f);
142	    }
143	    glEnd();
144	
145	    glBegin(GL_QUAD_STRIP);
146	    for (int i = 0; i <= segments; ++i) {
147	        const float angle = (2.0f * kPi * static_cast<float>(i)) / static_cast<float>(segments);
148	        const float nx = std::cos(angle);
149	        const float nz = std::sin(angle);
150	        const float u = static_cast<float>(i) / static_cast<float>(segments) * 2.0f;
151	        glNormal3f(nx, 0.0f, nz);
152	        vertexTextured(Vec3{center.x + nx * radius, center.y - halfHeight, center.z + nz * radius}, u, 0.0f);
153	        vertexTextured(Vec3{center.x + nx * radius, center.y + halfHeight, center.z + nz * radius}, u, 1.0f);
154	    }
155	    glEnd();
156	}
157	
158	// Builds an OpenGL frustum for a vertical field of view + aspect ratio.
159	void setupPerspective(float fovDeg, float aspect, float nearPlane, float farPlane) {
160	    const float top = nearPlane * std::tan(degToRad(fovDeg) * 0.5f);
161	    const float right = top * aspect;
162	    glFrustum(-right, right, -top, top, nearPlane, farPlane);
163	}
164	
165	// Loads a right-handed look-at matrix into the current matrix stack.
166	void setupLookAt(const Vec3& eye, const Vec3& center, const Vec3& up) {
167	    const Vec3 f = normalize(center - eye);
168	    const Vec3 s = normalize(cross(f, up));
169	    const Vec3 u = cross(s, f);
170	    const std::array<float, 16> matrix = {
171	        s.x, u.x, -f.x, 0.0f,
172	        s.y, u.y, -f.y, 0.0f,
173	        s.z, u.z, -f.z, 0.0f,
174	        -dot(s, eye), -dot(u, eye), dot(f, eye), 1.0f,
175	    };
176	    glLoadMatrixf(matrix.data());
177	}
178	
179	// Unit forward vector for yaw/pitch in degrees.
180	Vec3 forwardFromAngles(float yawDeg, float pitchDeg) {
181	    const float yaw = degToRad(yawDeg);
182	    const float pitch = degToRad(pitchDeg);
183	    const float cp = std::cos(pitch);
184	    return normalize(Vec3{std::sin(yaw) * cp, std::sin(pitch), std::cos(yaw) * cp});
185	}
