203	void Renderer3D::init() {
204	    glClearDepth(1.0);
205	    glEnable(GL_DEPTH_TEST);
206	    glDepthMask(GL_TRUE);
207	    glDepthFunc(GL_LEQUAL);
208	    glEnable(GL_NORMALIZE);
209	    glDisable(GL_CULL_FACE);
210	    glEnable(GL_LIGHTING);
211	    glEnable(GL_LIGHT0);
212	    glEnable(GL_COLOR_MATERIAL);
213	    glColorMaterial(GL_FRONT_AND_BACK, GL_AMBIENT_AND_DIFFUSE);
214	    glEnable(GL_TEXTURE_2D);
215	    glEnable(GL_BLEND);
216	    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
217	
218	    const GLfloat ambient[] = {0.32f, 0.32f, 0.34f, 1.0f};
219	    const GLfloat diffuse[] = {0.9f, 0.9f, 0.85f, 1.0f};
220	    const GLfloat specular[] = {0.15f, 0.15f, 0.15f, 1.0f};
221	    glLightfv(GL_LIGHT0, GL_AMBIENT, ambient);
222	    glLightfv(GL_LIGHT0, GL_DIFFUSE, diffuse);
223	    glLightfv(GL_LIGHT0, GL_SPECULAR, specular);
224	
225	    texAsphalt_ = makeCheckerTexture(sf::Color(70, 72, 76), sf::Color(62, 64, 68), 16);
226	    texPavement_ = makeCheckerTexture(sf::Color(176, 170, 160), sf::Color(158, 152, 142), 8);
227	    texGrass_ = makeCheckerTexture(sf::Color(64, 130, 62), sf::Color(54, 112, 52), 12);
228	    texBrick_ = makeBrickTexture(sf::Color(150, 92, 70), sf::Color(190, 180, 170));
229	    texGlass_ = makeCheckerTexture(sf::Color(120, 160, 200), sf::Color(80, 110, 150), 6);
230	    texStripe_ = makeStripeTexture(sf::Color(235, 235, 235), sf::Color(200, 60, 60));
231	    texCloth_ = makeCheckerTexture(sf::Color(255, 255, 255), sf::Color(235, 235, 235), 4);
232	}
