234	void Renderer3D::beginFrame(const sf::RenderWindow& window, const CameraPose& camera) {
235	    const sf::Vector2u size = window.getSize();
236	    aspect_ = size.y == 0 ? 1.0f : static_cast<float>(size.x) / static_cast<float>(size.y);
237	
238	    glViewport(0, 0, static_cast<GLint>(size.x), static_cast<GLint>(size.y));
239	    glClearColor(0.56f, 0.72f, 0.92f, 1.0f);
240	    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
241	
242	    glMatrixMode(GL_PROJECTION);
243	    glLoadIdentity();
244	    setupPerspective(kFovDeg, aspect_, kNearPlane, kFarPlane);
245	
246	    eye_ = camera.position + Vec3{0.f, kEyeHeight, 0.f};
247	    forward_ = forwardFromAngles(camera.yawDeg, camera.pitchDeg);
248	    right_ = normalize(cross(forward_, Vec3{0.f, 1.f, 0.f}));
249	    up_ = cross(right_, forward_);
250	
251	    glMatrixMode(GL_MODELVIEW);
252	    glLoadIdentity();
253	    setupLookAt(eye_, eye_ + forward_, Vec3{0.f, 1.f, 0.f});
254	
255	    const GLfloat lightPos[] = {60.0f, 120.0f, 40.0f, 1.0f};
256	    glLightfv(GL_LIGHT0, GL_POSITION, lightPos);
257	}
