259	void Renderer3D::drawGroundPatch(float minX, float minZ, float maxX, float maxZ, float y,
260	                                 GLuint texture, const sf::Color& tint, float tile) const {
261	    glBindTexture(GL_TEXTURE_2D, texture);
262	    setColor(tint);
263	    glBegin(GL_QUADS);
264	    drawTexturedQuad(Vec3{minX, y, minZ}, Vec3{maxX, y, minZ}, Vec3{maxX, y, maxZ}, Vec3{minX, y, maxZ}, tile, tile);
265	    glEnd();
266	}
