268	void Renderer3D::drawBuilding(const Building& b) const {
269	    const Vec3 center{(b.minX + b.maxX) * 0.5f, b.height * 0.5f, (b.minZ + b.maxZ) * 0.5f};
270	    const float halfX = (b.maxX - b.minX) * 0.5f;
271	    const float halfZ = (b.maxZ - b.minZ) * 0.5f;
272	    const float halfY = b.height * 0.5f;
273	
274	    GLuint texture = texBrick_;
275	    sf::Color tint = sf::Color::White;
276	    switch (b.facadeKind) {
277	        case 0: tint = sf::Color(235, 200, 170); break;                       // bakery: warm brick
278	        case 1: tint = sf::Color(180, 190, 215); break;                       // police: blue-grey
279	        case 2: tint = sf::Color(205, 165, 130); break;                       // coffee: roast brown
280	        case 3: tint = sf::Color(225, 210, 175); break;                       // library: sandstone
281	        case 4: tint = sf::Color(195, 195, 195); break;                       // hardware: grey
282	        case 5: texture = texStripe_; break;                                  // hot-dog cart awning
283	        case 6: texture = texGlass_; tint = sf::Color(245, 210, 70); break;   // taxi: cab yellow
284	        case 7: texture = texPavement_; tint = sf::Color(205, 215, 225); break;  // fountain stone
285	        case 8: texture = texPavement_; tint = sf::Color(150, 105, 65); break;   // wooden bench
286	        case 9: tint = sf::Color(185, 160, 150); break;                       // apartments
287	        case 10: texture = texGlass_; break;                                  // office tower
288	        default: break;
289	    }
290	
291	    const float tile = std::max(1.0f, halfY / 3.0f);
292	    drawTexturedBox(center, halfX, halfY, halfZ, texture, tint, tile);
293	
294	    if (b.id == "fountain") {
295	        // Water surface just below the rim.
296	        glDisable(GL_LIGHTING);
297	        drawGroundPatch(b.minX + 0.7f, b.minZ + 0.7f, b.maxX - 0.7f, b.maxZ - 0.7f,
298	                        b.height - 0.25f, texGlass_, sf::Color(90, 160, 220), 2.f);
299	        glEnable(GL_LIGHTING);
300	    }
301	}
