303	void Renderer3D::drawCity(const City& city) {
304	    const float half = city.halfSize();
305	
306	    // Asphalt base over the whole walkable square.
307	    drawGroundPatch(-half, -half, half, half, 0.f, texAsphalt_, sf::Color::White, half / 4.f);
308	
309	    // Sidewalk pads under the nine blocks (centers at -64/0/64, +-26 with curb
310	    // overhang past the 24-unit block so buildings sit on pavement).
311	    for (int bx = -1; bx <= 1; ++bx) {
312	        for (int bz = -1; bz <= 1; ++bz) {
313	            const float cx = static_cast<float>(bx) * 64.f;
314	            const float cz = static_cast<float>(bz) * 64.f;
315	            const bool park = bx == 1 && bz == 1;
316	            drawGroundPatch(cx - 26.f, cz - 26.f, cx + 26.f, cz + 26.f, 0.04f,
317	                            park ? texGrass_ : texPavement_,
318	                            sf::Color::White, park ? 6.f : 10.f);
319	        }
320	    }
321	
322	    for (const auto& building : city.buildings()) {
323	        drawBuilding(building);
324	    }
325	}
