327	void Renderer3D::drawNpc(const NpcVisual& npc) {
328	    const auto& palette = kNpcPalettes[static_cast<std::size_t>(npc.palette) % kNpcPalettes.size()];
329	    const sf::Color body = palette[0];
330	    const sf::Color accent = palette[1];
331	    const sf::Color skin(235, 200, 175);
332	
333	    glPushMatrix();
334	    glTranslatef(npc.position.x, npc.position.y, npc.position.z);
335	    glRotatef(-npc.facingDeg, 0.0f, 1.0f, 0.0f);
336	
337	    // Legs, torso, head, and a short visor/brim hinting at the facing side.
338	    drawTexturedCylinder(Vec3{0.f, 0.45f, 0.f}, 0.26f, 0.45f, 14, texCloth_, accent);
339	    drawTexturedCylinder(Vec3{0.f, 1.18f, 0.f}, 0.32f, 0.32f, 14, texCloth_, body);
340	    drawTexturedBox(Vec3{0.f, 1.68f, 0.f}, 0.17f, 0.18f, 0.17f, texCloth_, skin, 1.f);
