346	bool Renderer3D::worldToScreen(const Vec3& world, const sf::RenderWindow& window, sf::Vector2f& out) const {
347	    const Vec3 rel = world - eye_;
348	    const float zCam = dot(forward_, rel);
349	    if (zCam <= kNearPlane) return false;
350	
351	    const float xCam = dot(right_, rel);
352	    const float yCam = dot(up_, rel);
353	    const float tanHalf = std::tan(degToRad(kFovDeg) * 0.5f);
354	
355	    const float ndcX = xCam / (zCam * tanHalf * aspect_);
356	    const float ndcY = yCam / (zCam * tanHalf);
357	
358	    const sf::Vector2u size = window.getSize();
359	    out.x = (ndcX * 0.5f + 0.5f) * static_cast<float>(size.x);
360	    out.y = (0.5f - ndcY * 0.5f) * static_cast<float>(size.y);
361	    return true;
362	}
