17	// Drains the client every few milliseconds until a reply with `id` arrives or
18	// the deadline passes. Deltas drained along the way are appended to *deltas.
19	ChatReply waitForReply(LlmClient& client, std::uint64_t id,
20	                       std::vector<ChatDelta>* deltas = nullptr,
21	                       std::chrono::seconds timeout = std::chrono::seconds(10)) {
22	    const auto deadline = std::chrono::steady_clock::now() + timeout;
23	    while (std::chrono::steady_clock::now() < deadline) {
24	        if (deltas) {
25	            for (auto& d : client.drainDeltas()) deltas->push_back(std::move(d));
26	        }
27	        for (auto& reply : client.drainReplies()) {
28	            if (reply.id == id) return reply;
29	        }
30	        std::this_thread::sleep_for(std::chrono::milliseconds(5));
31	    }
32	    ChatReply timedOut;
33	    timedOut.id = id;
34	    timedOut.errorMessage = "test timed out waiting for reply";
35	    return timedOut;
36	}
