25	// Runs one full ask -> reply -> onReplyArrived round trip, returning the
26	// assistant text the NPC accepted (empty on failure or timeout).
27	std::string exchange(Npc& npc, LlmClient& client, const std::string& line) {
28	    const auto id = npc.ask(line);
29	    const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(10);
30	    while (std::chrono::steady_clock::now() < deadline) {
31	        for (const auto& reply : client.drainReplies()) {
32	            if (reply.id != id) continue;
33	            const std::optional<std::string> text = npc.onReplyArrived(reply);
34	            return text.value_or("");
35	        }
36	        std::this_thread::sleep_for(std::chrono::milliseconds(5));
37	    }
38	    return {};
39	}
