9	// A Persona is the static identity of an NPC. It is rendered into a single
10	// system-prompt string that is prepended to every chat request.
11	struct Persona {
12	    std::string name;                 // "Companion", "Jim", "Jane #47"
13	    std::string role;                 // "traveling companion", "pharmacist"
14	    std::vector<std::string> traits;  // "curious", "soft-spoken", ...
15	    std::string speakingStyle;        // "short sentences, 1-3 per reply"
16	    std::string knowledgeBoundary;    // what they do / do not know
17	    std::string extraDirectives;      // free-form constraints
18	
19	    std::string renderSystemPrompt() const {
20	        std::ostringstream o;
21	        o << "You are " << name;
22	        if (!role.empty()) o << ", a " << role;
23	        o << ".\n";
24	        if (!traits.empty()) {
25	            o << "Personality: ";
26	            for (size_t i = 0; i < traits.size(); ++i) {
27	                if (i) o << ", ";
28	                o << traits[i];
29	            }
30	            o << ".\n";
31	        }
32	        if (!speakingStyle.empty()) o << "Speaking style: " << speakingStyle << "\n";
33	        if (!knowledgeBoundary.empty()) o << "Knowledge: " << knowledgeBoundary << "\n";
34	        if (!extraDirectives.empty()) o << extraDirectives << "\n";
35	        o << "Stay in character. Never break the fourth wall. "
36	             "Never mention being an AI or a language model.";
37	        return o.str();
38	    }
39	};
