6	
7	Npc::Npc(Persona persona, LlmClient& client, int maxHistoryTurns)
8	    : persona_(std::move(persona)), client_(client), maxHistoryTurns_(maxHistoryTurns) {}
9	
10	std::uint64_t Npc::ask(const std::string& playerLine) {
11	    // Send a snapshot of the current history; the player line is appended to
12	    // history only once a successful reply arrives. That way a failed request
13	    // can be retried without polluting context with unanswered user turns.
14	    pendingUserLine_ = playerLine;
15	    pendingId_ = client_.submit(persona_.renderSystemPrompt(), history_, playerLine);
16	    return pendingId_;
17	}
18	
19	std::optional<std::string> Npc::onReplyArrived(const ChatReply& reply) {
20	    if (reply.id != pendingId_) return std::nullopt;
21	    pendingId_ = 0;
22	
23	    if (!reply.ok) {
24	        // Don't append anything on failure — let the UI report the error and
25	        // let the player retry. Clear the pending user line too.
26	        pendingUserLine_.clear();
27	        return std::nullopt;
28	    }
29	
30	    history_.push_back({"user", std::move(pendingUserLine_)});
31	    history_.push_back({"assistant", reply.content});
32	    pendingUserLine_.clear();
33	    trimHistory();
34	    return reply.content;
35	}
36	
37	void Npc::trimHistory() {
38	    // History is a flat list of role/content turns. Two entries (user +
39	    // assistant) make one round-trip turn, hence the *2 cap.
40	    const int maxEntries = maxHistoryTurns_ * 2;
41	    if (static_cast<int>(history_.size()) <= maxEntries) return;
42	    const int drop = static_cast<int>(history_.size()) - maxEntries;
43	    history_.erase(history_.begin(), history_.begin() + drop);
44	}
45	
46	}  // namespace llm_npc
